ValidationRule.errorConditionFormula:
AND( OR( RecordType.DeveloperName = "Guardian", RecordType.DeveloperName = "Student" ),
/* Only enforce when NOT coming from SchoolMint (type-specific) */ OR( AND( RecordType.DeveloperName = "Guardian", ISBLANK(SchoolMint_Guardian_Id__pc) ), AND( RecordType.DeveloperName = "Student", ISBLANK(SchoolMint_Student_Id__pc) ) ),
OR( ISBLANK(PersonMailingStreet), ISBLANK(PersonMailingCity), ISBLANK(PersonMailingState), ISBLANK(PersonMailingPostalCode), ISBLANK(PersonMailingCountry) ) )
